import { moduleMetadata } from '@storybook/angular';
import { UniSearchInputComponent as Search } from './search-input.component';
import { UniBoxDirective } from '../layout';
const SUGGESTIONS = [
    'oklch color engine',
    'ok computer',
    'okta integration',
    'theme tokens',
    'theme builder',
    'typography scale',
];
const meta = {
    title: 'Components/Forms/Search Input',
    component: Search,
    decorators: [moduleMetadata({ imports: [UniBoxDirective] })],
    argTypes: {
        label: { control: 'text', description: 'Accessible name; placeholder fallback.' },
        placeholder: { control: 'text', description: 'Placeholder override.' },
        debounceTime: { control: 'number', description: 'Pause before `searchChange` emits. Default: 400ms' },
        suggestions: {
            control: 'object',
            description: 'Type-ahead entries; refresh them from `searchChange` emissions.',
        },
        width: { control: 'text', description: "Field width. Default: '100%'" },
    },
};
export default meta;
export const Primary = {
    args: { label: 'Search' },
};
export const TypeAhead = {
    name: 'Type-ahead',
    render: () => ({
        props: {
            all: SUGGESTIONS,
            suggestions: [],
            filter(query) {
                this.suggestions = query
                    ? this.all.filter((s) => s.toLowerCase().includes(query.toLowerCase()))
                    : [];
            },
            log(value) {
                console.log('search:', value);
            },
        },
        template: `
      <div box-layout maxWidth="420px">
        <uni-search-input
          label="Search the docs"
          [debounceTime]="200"
          [suggestions]="suggestions"
          (searchChange)="filter($event)"
          (searchSubmit)="log($event)"
        ></uni-search-input>
      </div>
    `,
    }),
};
